package main

import "fmt"

func countPrimes(n int) int {
	if n < 3 {
		return 0
	}
	isPrime := make([]bool, n)
	for i := 2; i < n; i++ {
		isPrime[i] = true
	}
	for i := 2; i*i < n; i++ {
		if isPrime[i] {
			for multiple := i * i; multiple < n; multiple += i {
				isPrime[multiple] = false
			}
		}
	}
	count := 0
	for _, prime := range isPrime {
		if prime {
			count++
		}
	}
	return count
}

func main() {
	var n int
	fmt.Scan(&n)
	fmt.Println(countPrimes(n))
}

